class MeteorClient:
    def __init__(self, server):
        self.server = server
        self.ws = None
        self.connected = False
        self.subscriptions = {}
        self.call_callbacks = {}
        self.logged_in = False
        self.session_id = None
        self.user_id = None
        self.token = None
        self.message_id = 1

    def connect(self):
        self.ws = websocket.create_connection(self.server)
        msg = {
            "msg": "connect",
            "version": "1",
            "support": ["1"]
        }
        self.send(msg)
        response = self.receive()
        if response.get("msg") == "connected":
            self.connected = True
            self.session_id = response.get("session")
            return True
        return False

    def close(self):
        if self.ws:
            self.ws.close()
        self.connected = False

    def send(self, msg):
        if self.ws:
            self.ws.send(json.dumps(msg))

    def receive(self):
        if self.ws:
            response = self.ws.recv()
            return json.loads(response)
        return None

    def login(self, username, password):
        # Generate random ID for the message
        msg_id = ''.join(random.choices(string.ascii_lowercase + string.digits, k=17))

        # Create the login message using SHA-256 hashed password
        login_msg = {
            "msg": "method",
            "method": "login",
            "params": [{"user": {"username": username}, "password": password}],
            "id": msg_id
        }

        self.send(login_msg)

        # Wait for response
        while True:
            response = self.receive()
            print(f"Login response: {response}")

            if response.get("msg") == "result" and response.get("id") == msg_id:
                if "error" in response:
                    return False, response["error"]
                self.logged_in = True
                self.user_id = response.get("result", {}).get("id")
                self.token = response.get("result", {}).get("token")
                return True, response.get("result")

            # If we get an unexpected message, let's keep trying for a bit
            if "subs" not in response.get("msg", ""):
                continue

        return False, "No response"

    def call(self, method, params=None):
        if not params:
