// Connect to the Meteor server's WebSocket endpoint
const ws = new WebSocket('ws://web.chal.csaw.io:5000/websocket');

// Keep track of IDs
let connectionId = '1';
let methodId = '2';
let subscriptionId = '3';

// Flag to indicate if we're connected
let connected = false;

// Message queue and response handler
const messages = [];
const responseHandlers = {};

// Helper for sending messages
function sendMessage(msg) {
    console.log('Sending:', JSON.stringify(msg));
    messages.push(msg);

    if (connected) {
        ws.send(JSON.stringify(msg));
    }
}

// When the connection is established
ws.on('open', function open() {
    console.log('Connected to server');

    // Send connect message
    sendMessage({
        msg: 'connect',
        version: '1',
        support: ['1']
    });
});

// When we receive a message
ws.on('message', function incoming(data) {
    const msg = JSON.parse(data);
    console.log('Received:', JSON.stringify(msg));

    // Handle connection established
    if (msg.msg === 'connected') {
        connected = true;

        // Send queued messages
        while (messages.length > 0) {
            const queuedMsg = messages.shift();
            ws.send(JSON.stringify(queuedMsg));
        }

        // Try calling methods to find data
        callMethodFindTerryNotes();
