    });

    responseHandlers[findPasswordNotesId] = function(response) {
        console.log('Password notes response:', response);
    };

    // 4. Try to find notes with flag
    const findFlagNotesId = methodId++;
    sendMessage({
        msg: 'method',
        method: 'notes.find',
        params: [{ body: { $regex: 'flag' } }],
        id: findFlagNotesId
    });

    responseHandlers[findFlagNotesId] = function(response) {
        console.log('Flag notes response:', response);
    };

    // 5. Subscribe to notes.private
    sendMessage({
