#!/usr/bin/env python3
import socket
import json
import random
import string
import time

class DDPClient:
    def __init__(self, host, port=80, path='websocket'):
        self.host = host
        self.port = port
        self.path = path
        self.session = None
        self.socket = None
        self.msg_id = 1
        self.subs = {}
        self.connect()

    def connect(self):
        self.socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.socket.connect((self.host, self.port))
        http_req = f"GET /{self.path} HTTP/1.1\r\nHost: {self.host}:{self.port}\r\nConnection: Upgrade\r\nPragma: no-cache\r\nCache-Control: no-cache\r\nUpgrade: websocket\r\nSec-WebSocket-Version: 13\r\nSec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==\r\n\r\n"
        self.socket.send(http_req.encode())

        # Skip HTTP response
        data = b""
        while b"\r\n\r\n" not in data:
            data += self.socket.recv(1024)

        # Connect to DDP server
        self._send_message({
            "msg": "connect",
            "version": "1",
            "support": ["1"]
        })

        # Wait for connected message
        while True:
            msg = self._receive_message()
            if msg.get("msg") == "connected":
                self.session = msg.get("session")
                break

    def _send_message(self, msg):
        message = json.dumps(msg)
        self.socket.send(message.encode() + b"\n")

    def _receive_message(self):
        data = b""
        while b"\n" not in data:
            chunk = self.socket.recv(1024)
            if not chunk:
                raise ConnectionError("Connection closed")
            data += chunk
        message = data.split(b"\n")[0]
        return json.loads(message)

    def call(self, method, params=None, wait=True):
        params = params or []
        message_id = str(self.msg_id)
        self.msg_id += 1

        self._send_message({
            "msg": "method",
            "method": method,
            "params": params,
            "id": message_id
        })

        if wait:
            while True:
                msg = self._receive_message()
                if msg.get("msg") == "result" and msg.get("id") == message_id:
                    return msg.get("result")

    def subscribe(self, name, params=None):
        params = params or []
        sub_id = ''.join(random.choice(string.ascii_letters + string.digits) for _ in range(17))

        self._send_message({
            "msg": "sub",
            "id": sub_id,
            "name": name,
            "params": params
        })

        self.subs[sub_id] = {
            "name": name,
            "params": params
        }

        return sub_id

    def get_subscription_data(self, timeout=5):
        results = []
        start_time = time.time()

        while time.time() - start_time < timeout:
            try:
                msg = self._receive_message()
                if msg.get("msg") in ["added", "changed", "removed"]:
                    results.append(msg)
            except:
                break

        return results

    def login_with_password(self, username, password):
        return self.call("login", [{"user": {"username": username}, "password": password}])

    def register_user(self, username, password, email=None):
        options = {"username": username, "password": password}
        if email:
            options["email"] = email
        return self.call("createUser", [options])

#!/usr/bin/env python3
import socket
import json
import uuid
import time

class DDPClient:
    def __init__(self, host, port=80, path="websocket"):
        self.host = host
        self.port = port
        self.path = path
        self.socket = None
        self.session = None
        self.connect()

    def connect(self):
        """Connect to the DDP server and perform handshake"""
        self.socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.socket.connect((self.host, self.port))

        # Send WebSocket-like HTTP upgrade request
        upgrade_request = (
            f"GET /{self.path} HTTP/1.1\r\n"
            f"Host: {self.host}:{self.port}\r\n"
            "Upgrade: websocket\r\n"
            "Connection: Upgrade\r\n"
            "Sec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==\r\n"
            "Sec-WebSocket-Version: 13\r\n"
            "\r\n"
        )
        self.socket.sendall(upgrade_request.encode())

        # Read HTTP response (and discard it, we're expecting 101 Switching Protocols)
        response = b""
        while b"\r\n\r\n" not in response:
            chunk = self.socket.recv(4096)
            if not chunk:
                raise ConnectionError("Connection closed during handshake")
            response += chunk

        # Send DDP connect message
        self._send_message({
            "msg": "connect",
            "version": "1",
            "support": ["1"]
        })

        # Wait for connected message
        for _ in range(10):  # Try a few times
            msg = self._receive_message()
            if msg.get("msg") == "connected":
                self.session = msg.get("session")
                print(f"[+] Connected to DDP server, session: {self.session}")
                return
            elif msg.get("msg") == "failed":
                raise ConnectionError(f"Failed to connect: {msg}")

        raise ConnectionError("Did not receive connected message")

    def _send_message(self, message):
        """Send a message to the server"""
        data = json.dumps(message).encode() + b"\n"
        self.socket.sendall(data)

    def _receive_message(self, timeout=5):
        """Receive a message from the server"""
        self.socket.settimeout(timeout)
        data = b""
        try:
            while b"\n" not in data:
                chunk = self.socket.recv(4096)
                if not chunk:
                    raise ConnectionError("Connection closed")
                data += chunk
        except socket.timeout:
            return {}

        self.socket.settimeout(None)
        message = json.loads(data.decode().strip())
        return message

    def call(self, method, params=None, wait_for_result=True):
        """Call a method on the server"""
        if params is None:
            params = []

        id = str(uuid.uuid4())
        self._send_message({
            "msg": "method",
            "method": method,
            "params": params,
            "id": id
        })

        if wait_for_result:
            # Wait for the result
            deadline = time.time() + 10
            while time.time() < deadline:
                msg = self._receive_message()
                if msg.get("msg") == "result" and msg.get("id") == id:
                    return msg.get("result")

            return {"error": "No result received within timeout"}

        return {"status": "called"}

    def subscribe(self, name, params=None):
        """Subscribe to a publication"""
        if params is None:
            params = []

        id = str(uuid.uuid4())
        self._send_message({
            "msg": "sub",
            "name": name,
            "params": params,
            "id": id
        })

        # Wait for the subscription to be ready
        deadline = time.time() + 5
        while time.time() < deadline:
            msg = self._receive_message(timeout=1)
            if msg.get("msg") == "ready" and id in msg.get("subs", []):
                return {"status": "subscribed", "id": id}

        return {"status": "subscription_timeout"}

    def get_subscription_data(self, timeout=5):
        """Get data that has been published to subscriptions"""
        deadline = time.time() + timeout
        collection_data = {}

        while time.time() < deadline:
            msg = self._receive_message(timeout=0.5)
            if not msg:
                continue

            if msg.get("msg") == "added":
                collection = msg.get("collection")
                if collection not in collection_data:
                    collection_data[collection] = {}

                collection_data[collection][msg.get("id")] = msg.get("fields", {})

            elif msg.get("msg") == "changed":
                collection = msg.get("collection")
                if collection in collection_data and msg.get("id") in collection_data[collection]:
                    collection_data[collection][msg.get("id")].update(msg.get("fields", {}))

        return collection_data

    def login_with_password(self, username, password):
        """Log in with username and password"""
        return self.call("login", [{
            "user": {"username": username},
            "password": {
                "digest": password,  # In a real implementation, we would hash the password
                "algorithm": "sha-256"
            }
        }])

    def register_user(self, username, password):
        """Register a new user"""
        return self.call("createUser", [{
            "username": username,
            "password": password
        }])

    def close(self):
        """Close the connection"""
        if self.socket:
            self.socket.close()
            self.socket = None

