import hashlib
import ssl
import random
import string

def random_string(length=8):
    return ''.join(random.choice(string.ascii_lowercase + string.digits) for _ in range(length))

def sha256(password):
    return hashlib.sha256(password.encode()).hexdigest()

class MeteorClient:
    def __init__(self, server_url):
        self.server_url = server_url
        self.ws = None
        self.session_id = None
        self.connected = False
        self.subs = {}
        self.collections = {}

    def connect(self):
        # Connect to the WebSocket server
        self.ws = websocket.create_connection(self.server_url, sslopt={"cert_reqs": ssl.CERT_NONE})

        # Send connect message
        self.ws.send(json.dumps({
            "msg": "connect",
            "version": "1",
            "support": ["1"]
        }))

        # Wait for connected message
        response = json.loads(self.ws.recv())
        if response.get("msg") == "connected":
            self.session_id = response.get("session")
            self.connected = True
            print(f"[+] Connected to Meteor server. Session ID: {self.session_id}")
        else:
            print(f"[-] Failed to connect: {response}")

    def register(self, username, password):
        method_id = str(uuid.uuid4())
        self.ws.send(json.dumps({
            "msg": "method",
            "method": "createUser",
            "params": [{
                "username": username,
                "password": password
            }],
            "id": method_id
        }))

        # Wait for the result
        while True:
            response = json.loads(self.ws.recv())
            if response.get("msg") == "result" and response.get("id") == method_id:
                if "error" in response:
                    print(f"[-] Registration failed: {response['error']['reason']}")
                    return None
                else:
                    print(f"[+] Registration successful: {response}")
                    return response.get("result")

    def login(self, username, password):
        method_id = str(uuid.uuid4())

        # For Meteor, we should hash the password
        hashed_password = sha256(password)

        self.ws.send(json.dumps({
            "msg": "method",
            "method": "login",
            "params": [{
                "user": {"username": username},
                "password": {
                    "digest": hashed_password,
                    "algorithm": "sha-256"
                }
            }],
            "id": method_id
        }))

        # Wait for the result
        while True:
            response = json.loads(self.ws.recv())
            if response.get("msg") == "result" and response.get("id") == method_id:
                if "error" in response:
                    print(f"[-] Login failed: {response['error']['reason']}")
                    return None
                else:
                    print(f"[+] Login successful")
                    return response.get("result")

    def call_method(self, method, params=None, wait=True):
        if params is None:
            params = []

        method_id = str(uuid.uuid4())
        self.ws.send(json.dumps({
            "msg": "method",
            "method": method,
            "params": params,
            "id": method_id
        }))

        if wait:
            # Wait for the result
            while True:
                response = json.loads(self.ws.recv())
                if response.get("msg") == "result" and response.get("id") == method_id:
                    if "error" in response:
                        print(f"[-] Method call failed: {response.get('error', {}).get('reason', 'Unknown error')}")
                    return response

    def subscribe(self, name, params=None):
        if params is None:
            params = []

        sub_id = str(uuid.uuid4())
        self.ws.send(json.dumps({
            "msg": "sub",
            "id": sub_id,
            "name": name,
            "params": params
        }))

        self.subs[sub_id] = {
            "name": name,
            "params": params,
            "ready": False
        }

        # Wait for ready message
        deadline = time.time() + 5
        while time.time() < deadline:
            response = json.loads(self.ws.recv())
            if response.get("msg") == "ready" and sub_id in response.get("subs", []):
                self.subs[sub_id]["ready"] = True
                print(f"[+] Subscription {name} ready")
                return sub_id
            elif "collection" in response:
                # This is data for one of our subscriptions
                collection = response.get("collection")
                if collection not in self.collections:
                    self.collections[collection] = {}

                if response.get("msg") == "added":
                    doc_id = response.get("id")
                    self.collections[collection][doc_id] = response.get("fields", {})
                    print(f"[+] Added document to {collection}: {self.collections[collection][doc_id]}")

        print(f"[-] Subscription {name} not ready in time")
        return None

    def process_messages(self, timeout=2):
        """Process any pending messages for a period of time"""
        self.ws.settimeout(0.1)  # Short timeout for non-blocking
        deadline = time.time() + timeout

        while time.time() < deadline:
            try:
                response = json.loads(self.ws.recv())
                if "collection" in response:
                    # This is collection data
                    collection = response.get("collection")
                    if collection not in self.collections:
                        self.collections[collection] = {}

                    if response.get("msg") == "added":
                        doc_id = response.get("id")
                        self.collections[collection][doc_id] = response.get("fields", {})
                        print(f"[+] Added document to {collection}: {self.collections[collection][doc_id]}")

                    elif response.get("msg") == "changed":
                        doc_id = response.get("id")
                        if doc_id in self.collections[collection]:
                            fields = response.get("fields", {})
                            self.collections[collection][doc_id].update(fields)
                            print(f"[+] Updated document in {collection}: {self.collections[collection][doc_id]}")

                elif response.get("msg") == "ready":
                    for sub_id in response.get("subs", []):
                        if sub_id in self.subs:
                            self.subs[sub_id]["ready"] = True
                            print(f"[+] Subscription {self.subs[sub_id]['name']} is now ready")

            except websocket.WebSocketTimeoutException:
                pass
            except Exception as e:
                print(f"[-] Error processing messages: {e}")
                break

        self.ws.settimeout(None)

    def get_collection(self, name):
        return self.collections.get(name, {})

    def close(self):
        if self.ws:
            self.ws.close()

