import json
import random
import string
import time
import websocket
import threading
import ssl

class DDPClient:
    def __init__(self, url, debug=False):
        self.url = url
        self.debug = debug
        self.ws = None
        self.connected = False
        self.session = None
        self.version = "1"
        self.subscriptions = {}
        self.methods = {}
        self._next_id = 0
        self._messages = {}
        self.collections = {}

    def _get_id(self):
        self._next_id += 1
        return str(self._next_id)

    def connect(self):
        self.ws = websocket.create_connection(self.url, sslopt={"cert_reqs": ssl.CERT_NONE})

        msg = {
            "msg": "connect",
            "version": self.version,
            "support": [self.version]
        }
        self._send(msg)

        response = self._recv()
        if response.get("msg") != "connected":
            raise Exception("Failed to connect to server")

        self.connected = True
        self.session = response.get("session")

        if self.debug:
            print(f"Connected to {self.url} with session {self.session}")

        return self.connected

    def _send(self, msg):
        if self.debug:
            print(f">>> {json.dumps(msg)}")
        self.ws.send(json.dumps(msg))

    def _recv(self):
        data = self.ws.recv()
        if self.debug:
            print(f"<<< {data}")
        return json.loads(data)

    def _wait_for_msg(self, msg_id, timeout=10):
        start = time.time()
        while time.time() - start < timeout:
            for msg in self._messages.get(msg_id, []):
                return msg
            time.sleep(0.01)
        return None

    def call(self, method, params=None, wait=True, timeout=10):
        if not self.connected:
            self.connect()

        msg_id = self._get_id()
        msg = {
            "msg": "method",
            "method": method,
            "id": msg_id
        }

        if params is not None:
            if not isinstance(params, list):
                params = [params]
            msg["params"] = params

        self._send(msg)

        if wait:
            start = time.time()
            while time.time() - start < timeout:
                response = self._recv()
                if response.get("msg") == "result" and response.get("id") == msg_id:
                    if "error" in response:
                        if self.debug:
                            print(f"Error calling {method}: {response['error']}")
                        return {"success": False, "error": response["error"]}
                    return {"success": True, "result": response.get("result")}
                # Handle other messages (changes, etc.)
                msg_type = response.get("msg")
                if msg_type == "added" or msg_type == "changed" or msg_type == "removed":
                    collection = response.get("collection")
                    if collection not in self.collections:
                        self.collections[collection] = {}

                    if msg_type == "added" or msg_type == "changed":
                        doc_id = response.get("id")
                        fields = response.get("fields", {})
                        if doc_id not in self.collections[collection]:
                            self.collections[collection][doc_id] = {}
                        self.collections[collection][doc_id].update(fields)

                    elif msg_type == "removed":
                        doc_id = response.get("id")
                        if doc_id in self.collections[collection]:
                            del self.collections[collection][doc_id]

        return {"success": True, "id": msg_id}

    def subscribe(self, name, params=None, wait=True, timeout=10):
        if not self.connected:
            self.connect()

        msg_id = self._get_id()
        msg = {
            "msg": "sub",
            "name": name,
            "id": msg_id
        }

        if params is not None:
            if not isinstance(params, list):
                params = [params]
            msg["params"] = params

        self._send(msg)

        if wait:
            start = time.time()
            while time.time() - start < timeout:
                response = self._recv()
                if response.get("msg") == "ready" and msg_id in response.get("subs", []):
                    self.subscriptions[msg_id] = name
                    return {"success": True, "id": msg_id}
                if response.get("msg") == "nosub" and response.get("id") == msg_id:
                    if "error" in response:
                        if self.debug:
                            print(f"Error subscribing to {name}: {response['error']}")
                        return {"success": False, "error": response["error"]}
                    return {"success": False}

                # Handle other messages
                msg_type = response.get("msg")
                if msg_type == "added" or msg_type == "changed" or msg_type == "removed":
                    collection = response.get("collection")
                    if collection not in self.collections:
                        self.collections[collection] = {}

                    if msg_type == "added" or msg_type == "changed":
                        doc_id = response.get("id")
                        fields = response.get("fields", {})
                        if doc_id not in self.collections[collection]:
                            self.collections[collection][doc_id] = {}
                        self.collections[collection][doc_id].update(fields)

                    elif msg_type == "removed":
                        doc_id = response.get("id")
                        if doc_id in self.collections[collection]:
                            del self.collections[collection][doc_id]

        self.subscriptions[msg_id] = name
        return {"success": True, "id": msg_id}

    def unsubscribe(self, sub_id):
        if not self.connected:
            return False

        msg = {
            "msg": "unsub",
            "id": sub_id
        }

        self._send(msg)

        if sub_id in self.subscriptions:
            del self.subscriptions[sub_id]

        return True

    def close(self):
        if self.ws:
            self.ws.close()
        self.connected = False
        self.session = None
        self.subscriptions = {}
        self.methods = {}
        self.collections = {}

